fn absolute(n: i32) -> i32 {
    if n<0 {
        -n
    }
    else {
        n
    }
}

fn sum_to(n: u32) -> u32 {
    let mut total=0;
    for i in 1..=n {
        total+=i;
    }
    total
}

fn add_bang(s: &str) -> String {
    let mut out=s.to_owned();
    out.push('!');
    out
}

