lessons.solution:
fn parse_or(s: &str, fallback: i32) -> i32 {
    s.parse::<i32>().unwrap_or(fallback)
}

fn partial_sums(values: &[i32]) -> Vec<i32> {
    let mut total=0;
    let mut out=Vec::new();
    for &value in values {
        total+=value;
        out.push(total);
    }
    out
}

fn count_word(s: &str, wanted: &str) -> usize {
    let mut counts=std::collections::HashMap::new();
    for word in s.split_whitespace() {
        *counts.entry(word).or_insert(0usize)+=1;
    }
    counts.get(wanted).copied().unwrap_or(0)
}

fn is_prime(n: u32) -> bool {
    if n<2 {
        return false;
    }
    let mut d=2;
    while d<=n/d {
        if n%d==0 {
            return false;
        }
        d+=1;
    }
    true
}

fn fib(n: u32) -> u32 {
    let(mut a,mut b)=(0,1);
    for _ in 0..n {
        (a,b)=(b,a+b);
    }
    a
}

